    public enum Mode { ARMY, FIELD_OFFICERS, NAVY, NAVY_HQ, AIR, ASSIGN_ARMY, ASSIGN_MARSHAL, PROMOTE, CREATE_ARMY, MOVE_DIVISIONS, NAVAL_TASK_FORCES, NAVAL_MISSION, AIR_MISSION, ARMY_PLANS, LAND_PLAN, ARMY_UNITS, PLAN_UNITS, ARMY_GROUPS, ARMY_GROUP, ARMY_GROUP_MEMBERS, ASSIGN_GROUP_MARSHAL, NAVY_FLEET, NAVY_FLEET_MEMBERS, NAVAL_ORDERS, AIR_ORDERS, NAVY_HEADQUARTERS, COMMANDER_TRAITS, COMMANDER_TRAIT_CONFIRM, COMMANDER_TACTICS, COMMANDER_TACTIC_CONFIRM, COMMANDER_ADVISOR_ROLES, COMMANDER_ADVISOR_CONFIRM, AIR_ATTACH, NAVAL_TOOLBAR, AIR_TOOLBAR, ARMY_TOOLBAR, AIR_ORGANIZE, NAVAL_SETTINGS, NAVAL_INVASION_PLANS, NAVAL_ORGANIZE, AIR_GROUPS, AIR_REINFORCEMENT, NAVAL_AREAS, NAVAL_REINFORCEMENT, ARMY_ABILITIES, ORGANIZATION, ORGANIZATION_POLICIES, SHIP_CAPTAINS }
    public record Open(Mode mode,String target,List<String> selection) implements CustomPacketPayload {
        public Open {Objects.requireNonNull(mode);id(target,160);selection=List.copyOf(selection);if(selection.size()>2048||selection.stream().distinct().count()!=selection.size())throw new IllegalArgumentException("Invalid commander selection");selection.forEach(s->id(s,160));}
        public Open(Mode mode,String target){this(mode,target,List.of());}
        public static final Type<Open> TYPE=new Type<>(Identifier.parse("hoi:commander_open_v1"));
        public static final StreamCodec<RegistryFriendlyByteBuf,Open> CODEC=StreamCodec.of((b,p)->{b.writeEnum(p.mode);b.writeUtf(p.target,160);b.writeVarInt(p.selection.size());p.selection.forEach(s->b.writeUtf(s,160));},b->{var mode=b.readEnum(Mode.class);var target=b.readUtf(160);int n=b.readVarInt();if(n<0||n>2048)throw new IllegalArgumentException("Invalid commander selection count");var selection=new ArrayList<String>();for(int i=0;i<n;i++)selection.add(b.readUtf(160));return new Open(mode,target,selection);});
        @Override public Type<Open> type(){return TYPE;}
    }
    public record Ray(double x,double y,double z) {
        public Ray {double length=x*x+y*y+z*z;if(!Double.isFinite(length)||Math.abs(length-1)>.001||y>=-.00001)throw new IllegalArgumentException("Invalid land map ray");}
    }
    public record PlanMapPick(String token,long revision,boolean toggle,List<Ray> rays) implements CustomPacketPayload {
        public PlanMapPick {UUID.fromString(token);rays=List.copyOf(rays);if(revision<0||rays.isEmpty()||rays.size()>64||toggle&&rays.size()!=1)throw new IllegalArgumentException("Invalid land map selection");}
        public static final Type<PlanMapPick> TYPE=new Type<>(Identifier.parse("hoi:land_plan_map_v1"));
        public static final StreamCodec<RegistryFriendlyByteBuf,PlanMapPick> CODEC=StreamCodec.of((b,p)->{b.writeUtf(p.token,36);b.writeVarLong(p.revision);b.writeBoolean(p.toggle);b.writeVarInt(p.rays.size());for(var ray:p.rays){b.writeDouble(ray.x);b.writeDouble(ray.y);b.writeDouble(ray.z);}},b->{String token=b.readUtf(36);long revision=b.readVarLong();boolean toggle=b.readBoolean();int n=b.readVarInt();if(n<1||n>64)throw new IllegalArgumentException("Invalid land ray count");var rays=new ArrayList<Ray>();for(int i=0;i<n;i++)rays.add(new Ray(b.readDouble(),b.readDouble(),b.readDouble()));return new PlanMapPick(token,revision,toggle,rays);});
        @Override public Type<PlanMapPick> type(){return TYPE;}
    }
    public enum Arrow { MOVE, MISSION, RETREAT }
    public record MovementQuad(float x,float y,float z,float width,float length,float yaw,float u0,float v0,float u1,float v1,Arrow arrow) {
        public MovementQuad(float x,float y,float z,float width,float length,float yaw,float u0,float v0,float u1,float v1){this(x,y,z,width,length,yaw,u0,v0,u1,v1,Arrow.MOVE);}
        public MovementQuad {
            Objects.requireNonNull(arrow);
            for(float coordinate:new float[]{x,y,z,yaw})if(!Float.isFinite(coordinate)||Math.abs(coordinate)>65536)throw new IllegalArgumentException("Invalid movement coordinate");
            for(float size:new float[]{width,length})if(!Float.isFinite(size)||size<=0||size>8192)throw new IllegalArgumentException("Invalid movement size");
            for(float uv:new float[]{u0,v0,u1,v1})if(!Float.isFinite(uv)||uv<0||uv>1)throw new IllegalArgumentException("Invalid movement UV");
            if(u0>=u1||v0>=v1)throw new IllegalArgumentException("Empty movement UV");
        }
        private void write(RegistryFriendlyByteBuf b){for(float value:new float[]{x,y,z,width,length,yaw,u0,v0,u1,v1})b.writeFloat(value);b.writeEnum(arrow);}
        private static MovementQuad read(RegistryFriendlyByteBuf b){return new MovementQuad(b.readFloat(),b.readFloat(),b.readFloat(),b.readFloat(),b.readFloat(),b.readFloat(),b.readFloat(),b.readFloat(),b.readFloat(),b.readFloat(),b.readEnum(Arrow.class));}
    }
    public record PlanPoint(float x,float y,float z) {
        public PlanPoint {for(float coordinate:new float[]{x,y,z})if(!Float.isFinite(coordinate)||Math.abs(coordinate)>65536)throw new IllegalArgumentException("Invalid plan point");}
        private void write(RegistryFriendlyByteBuf b){b.writeFloat(x);b.writeFloat(y);b.writeFloat(z);}
        private static PlanPoint read(RegistryFriendlyByteBuf b){return new PlanPoint(b.readFloat(),b.readFloat(),b.readFloat());}
    }
    public record PlanPresentation(String id,String army,String type,boolean active,String posture,int divisions,String label,List<PlanPoint> front,List<PlanPoint> objectives) {
        public PlanPresentation {ProtocolCommanderHud.id(id,160);ProtocolCommanderHud.id(army,160);if(id.isEmpty()||army.isEmpty()||type==null||!type.matches("[A-Z_]{1,32}")||posture==null||!posture.matches("[A-Z_]{1,32}")||divisions<0||divisions>4096)throw new IllegalArgumentException("Invalid plan presentation");text(label,200);front=List.copyOf(front);objectives=List.copyOf(objectives);if(front.size()>512||objectives.size()>512)throw new IllegalArgumentException("Invalid plan presentation");}
        private void write(RegistryFriendlyByteBuf b){b.writeUtf(id,160);b.writeUtf(army,160);b.writeUtf(type,32);b.writeBoolean(active);b.writeUtf(posture,32);b.writeVarInt(divisions);b.writeUtf(label,200);for(var points:List.of(front,objectives)){b.writeVarInt(points.size());points.forEach(point->point.write(b));}}
        private static PlanPresentation read(RegistryFriendlyByteBuf b){String id=b.readUtf(160),army=b.readUtf(160),type=b.readUtf(32);boolean active=b.readBoolean();String posture=b.readUtf(32);int divisions=b.readVarInt();String label=b.readUtf(200);var lists=new ArrayList<List<PlanPoint>>();for(int list=0;list<2;list++){int count=b.readVarInt();if(count<0||count>512)throw new IllegalArgumentException("Oversized plan presentation");var points=new ArrayList<PlanPoint>(count);for(int i=0;i<count;i++)points.add(PlanPoint.read(b));lists.add(points);}return new PlanPresentation(id,army,type,active,posture,divisions,label,lists.get(0),lists.get(1));}
    }
    public enum AirArrowKind { MISSION, TRANSFER }
    public enum AirArrowState { SELECTED, ACTIVE, NONACTIVE }
    public record AirArrow(String wing,AirArrowKind kind,AirArrowState state,PlanPoint from,PlanPoint to) {
        public AirArrow {ProtocolCommanderHud.id(wing,160);if(wing.isEmpty())throw new IllegalArgumentException("Invalid air arrow");Objects.requireNonNull(kind);Objects.requireNonNull(state);Objects.requireNonNull(from);Objects.requireNonNull(to);}
        private void write(RegistryFriendlyByteBuf b){b.writeUtf(wing,160);b.writeEnum(kind);b.writeEnum(state);from.write(b);to.write(b);}
        private static AirArrow read(RegistryFriendlyByteBuf b){return new AirArrow(b.readUtf(160),b.readEnum(AirArrowKind.class),b.readEnum(AirArrowState.class),PlanPoint.read(b),PlanPoint.read(b));}
    }
    public record PlanOverlay(String country,ProtocolAtlasScene.Page page,List<MovementQuad> movement,List<PlanPresentation> plans,List<AirArrow> air) implements CustomPacketPayload {
        public PlanOverlay(String country,ProtocolAtlasScene.Page page,List<MovementQuad> movement,List<PlanPresentation> plans){this(country,page,movement,plans,List.of());}
        public PlanOverlay(String country,ProtocolAtlasScene.Page page,List<MovementQuad> movement){this(country,page,movement,List.of());}
        public PlanOverlay(String country,ProtocolAtlasScene.Page page){this(country,page,List.of());}
        public PlanOverlay {if(country==null||!country.isEmpty()&&!country.matches("[A-Z0-9]{3}"))throw new IllegalArgumentException("Invalid plan country");Objects.requireNonNull(page);movement=List.copyOf(movement);plans=plans==null?List.of():List.copyOf(plans);if(movement.size()>ProtocolAtlasScene.PAGE_SIZE)throw new IllegalArgumentException("Oversized movement page");if(plans.size()>128||plans.stream().map(PlanPresentation::id).distinct().count()!=plans.size())throw new IllegalArgumentException("Oversized plan page");air=air==null?List.of():List.copyOf(air);if(air.size()>1024||air.stream().map(AirArrow::wing).distinct().count()!=air.size())throw new IllegalArgumentException("Oversized air arrow page");}
        public static final Type<PlanOverlay> TYPE=new Type<>(Identifier.parse("hoi:land_plan_overlay_v5"));
        public static final StreamCodec<RegistryFriendlyByteBuf,PlanOverlay> CODEC=StreamCodec.of((b,p)->{b.writeUtf(p.country,3);ProtocolAtlasScene.Page.CODEC.encode(b,p.page);b.writeVarInt(p.movement.size());p.movement.forEach(q->q.write(b));b.writeVarInt(p.plans.size());p.plans.forEach(plan->plan.write(b));b.writeVarInt(p.air.size());p.air.forEach(arrow->arrow.write(b));},b->{String country=b.readUtf(3);var page=ProtocolAtlasScene.Page.CODEC.decode(b);int count=b.readVarInt();if(count<0||count>ProtocolAtlasScene.PAGE_SIZE)throw new IllegalArgumentException("Invalid movement page size");var quads=new ArrayList<MovementQuad>(count);for(int i=0;i<count;i++)quads.add(MovementQuad.read(b));int planCount=b.readVarInt();if(planCount<0||planCount>128)throw new IllegalArgumentException("Invalid plan page size");var plans=new ArrayList<PlanPresentation>(planCount);for(int i=0;i<planCount;i++)plans.add(PlanPresentation.read(b));int airCount=b.readVarInt();if(airCount<0||airCount>1024)throw new IllegalArgumentException("Invalid air arrow page size");var air=new ArrayList<AirArrow>(airCount);for(int i=0;i<airCount;i++)air.add(AirArrow.read(b));return new PlanOverlay(country,page,quads,plans,air);});
        @Override public Type<PlanOverlay> type(){return TYPE;}
    }
