    public record Snapshot(String json) implements CustomPacketPayload {
        public Snapshot {text(json,1000000);if(json.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>1000000)throw new IllegalArgumentException("Commander packet exceeds byte budget");}
        public static final Type<Snapshot> TYPE=new Type<>(Identifier.parse("hoi:commander_hud_v1"));
        public static final StreamCodec<RegistryFriendlyByteBuf,Snapshot> CODEC=StreamCodec.of((b,p)->b.writeUtf(p.json,1000000),b->new Snapshot(b.readUtf(1000000)));
        public static Snapshot of(View view){
            String json=JSON.toJson(view);if(bytes(json)<=900000)return new Snapshot(json);
            var cards=view.cards().stream().map(c->new Card(c.id(),c.name(),c.leader(),c.portrait(),c.marshal(),c.marshalPortrait(),c.count(),c.capacity(),c.detail(),c.role(),c.panel()==null?null:new Panel(c.panel().parent(),c.panel().commander(),null,List.of(),c.panel().total(),List.of(),c.panel().divisionIds()),c.tooltip())).toList();
            json=JSON.toJson(new View(view.country(),view.dimension(),view.branch(),cards,view.wings(),view.running(),view.theaters()));if(bytes(json)<=900000)return new Snapshot(json);
            cards=cards.stream().map(c->new Card(c.id(),c.name(),c.leader(),c.portrait(),c.marshal(),c.marshalPortrait(),c.count(),c.capacity(),"",c.role(),c.panel(),"")).toList();
            json=JSON.toJson(new View(view.country(),view.dimension(),view.branch(),cards,view.wings(),view.running(),view.theaters()));if(bytes(json)<=900000)return new Snapshot(json);
            var wings=view.wings().stream().map(w->new Member(w.id(),w.name(),w.status(),w.icon(),"",w.strength(),w.request(),w.selectionKey(),w.organization(),w.composition(),w.group(),w.mission(),w.data())).toList();
            json=JSON.toJson(new View(view.country(),view.dimension(),view.branch(),cards,wings,view.running(),view.theaters()));if(bytes(json)<=1000000)return new Snapshot(json);
            cards=cards.stream().map(c->new Card(c.id(),c.name(),c.leader(),c.portrait(),c.marshal(),c.marshalPortrait(),c.count(),c.capacity(),c.detail(),c.role(),c.panel()==null?null:new Panel(c.panel().parent(),c.panel().commander(),null,List.of(),c.panel().total(),List.of(),null),c.tooltip())).toList();
            return new Snapshot(JSON.toJson(new View(view.country(),view.dimension(),view.branch(),cards,wings,view.running(),view.theaters())));
        }
        private static int bytes(String value){return value.getBytes(java.nio.charset.StandardCharsets.UTF_8).length;}
        public View view(){return ProtocolJsonCodec.read(JSON,json,View.class);}
        @Override public Type<Snapshot> type(){return TYPE;}
    }
    public static synchronized void registerPayloadTypes(){if(registered)return;PayloadTypeRegistry.serverboundPlay().registerLarge(Open.TYPE,Open.CODEC,400000);PayloadTypeRegistry.clientboundPlay().register(Snapshot.TYPE,Snapshot.CODEC);PayloadTypeRegistry.serverboundPlay().register(PlanMapPick.TYPE,PlanMapPick.CODEC);PayloadTypeRegistry.clientboundPlay().register(PlanOverlay.TYPE,PlanOverlay.CODEC);PayloadTypeRegistry.serverboundPlay().register(SeaHover.TYPE,SeaHover.CODEC);PayloadTypeRegistry.clientboundPlay().register(SeaHoverTooltip.TYPE,SeaHoverTooltip.CODEC);registered=true;}
    private static void text(String s,int bound){if(s==null||s.length()>bound)throw new IllegalArgumentException("Invalid commander text");}
    private static void id(String s,int bound){text(s,bound);if(!s.isEmpty()&&!s.matches("[A-Za-z0-9_:/|.-]+"))throw new IllegalArgumentException("Invalid commander ID");}
    private static boolean ratio(Double v){return v==null||Double.isFinite(v)&&v>=0&&v<=1;}
    private static void asset(String s){text(s,180);if(!s.isEmpty()&&!s.matches("[a-z0-9_/-]+"))throw new IllegalArgumentException("Invalid commander portrait");}
